package laravelcrypt

import (
	"encoding/json"
	"errors"
	"os"
	"reflect"
	"strings"
	"testing"
	"time"
)

// Interop Envelope tokens made by the real Laravel encrypter and the laravel-interop package
// (fixtures/envelope-vectors.json, regenerated by bin/generate-vectors.php of that package).
// Every vector names the verdict all implementations have to reach.

type envelopeVector struct {
	Name         string          `json:"name"`
	Cipher       string          `json:"cipher"`
	Key          string          `json:"key"`
	Token        string          `json:"token"`
	PlaintextB64 *string         `json:"plaintext_b64"`
	Scope        string          `json:"scope"`
	Now          int64           `json:"now"`
	Leeway       int64           `json:"leeway"`
	Expect       string          `json:"expect"`
	ExpectNoPrev string          `json:"expect_without_previous_key"`
	Data         json.RawMessage `json:"data"`
	Iat          int64           `json:"iat"`
	Nbf          *int64          `json:"nbf"`
	Exp          *int64          `json:"exp"`
}

type envelopeFixtures struct {
	KeyB64         string           `json:"key_b64"`
	PreviousKeyB64 string           `json:"previous_key_b64"`
	Vectors        []envelopeVector `json:"vectors"`
	SealCases      []sealCase       `json:"seal_cases"`
}

type sealCase struct {
	Name      string          `json:"name"`
	Scope     string          `json:"scope"`
	Data      json.RawMessage `json:"data"`
	Expiry    map[string]any  `json:"expiry"`
	NotBefore *int64          `json:"not_before"`
	Now       int64           `json:"now"`
}

func loadEnvelopeFixtures(t *testing.T) envelopeFixtures {
	t.Helper()
	raw, err := os.ReadFile("fixtures/envelope-vectors.json")
	if err != nil {
		t.Fatalf("read fixtures/envelope-vectors.json: %v", err)
	}
	var f envelopeFixtures
	if err := json.Unmarshal(raw, &f); err != nil {
		t.Fatalf("parse fixtures/envelope-vectors.json: %v", err)
	}
	if len(f.Vectors) < 150 || len(f.SealCases) == 0 {
		t.Fatal("fixtures/envelope-vectors.json is incomplete")
	}
	return f
}

func envelopeEncrypter(t *testing.T, f envelopeFixtures, cipher string, rotated bool) *Encrypter {
	t.Helper()
	size := keySize(cipher)
	opts := []Option{}
	if rotated {
		opts = append(opts, WithPreviousKeys("base64:"+b64Encode(mustB64Decode(t, f.PreviousKeyB64)[:size])))
	}
	enc, err := New("base64:"+b64Encode(mustB64Decode(t, f.KeyB64)[:size]), cipher, opts...)
	if err != nil {
		t.Fatal(err)
	}
	return enc
}

func (v envelopeVector) options() []EnvelopeOption {
	return []EnvelopeOption{
		WithLeeway(time.Duration(v.Leeway) * time.Second),
		WithClock(func() time.Time { return time.Unix(v.Now, 0) }),
	}
}

// check compares the outcome of Open with what the vector expects.
func (v envelopeVector) check(t *testing.T, context string, o *Opened, err error) {
	t.Helper()
	name := context + v.Cipher + " " + v.Name
	if got := EnvelopeVerdict(err); got != v.Expect {
		t.Errorf("%s: verdict %q (%v), want %q", name, got, err, v.Expect)
		return
	}
	if err != nil {
		return
	}
	if o.IssuedAt.Unix() != v.Iat || o.Scope != v.Scope {
		t.Errorf("%s: issued at %d for %q, want %d for %q", name, o.IssuedAt.Unix(), o.Scope, v.Iat, v.Scope)
	}
	for _, f := range []struct {
		field string
		got   time.Time
		want  *int64
	}{{"nbf", o.NotBefore, v.Nbf}, {"exp", o.ExpiresAt, v.Exp}} {
		switch {
		case f.want == nil && !f.got.IsZero():
			t.Errorf("%s: %s = %v, want none", name, f.field, f.got)
		case f.want != nil && f.got.Unix() != *f.want:
			t.Errorf("%s: %s = %d, want %d", name, f.field, f.got.Unix(), *f.want)
		}
	}
	var got, want any
	if json.Unmarshal(o.Data, &got) != nil || json.Unmarshal(v.Data, &want) != nil || !reflect.DeepEqual(got, want) {
		t.Errorf("%s: data %s, want %s", name, o.Data, v.Data)
	}
}

func TestEveryVectorGetsTheVerdictTheLaravelPackageGives(t *testing.T) {
	f := loadEnvelopeFixtures(t)
	for _, v := range f.Vectors {
		enc := envelopeEncrypter(t, f, v.Cipher, v.Key == "previous")
		o, err := enc.Open(v.Token, v.Scope, v.options()...)
		v.check(t, "", o, err)

		if v.ExpectNoPrev != "" {
			plain := envelopeEncrypter(t, f, v.Cipher, false)
			if _, err := plain.Open(v.Token, v.Scope, v.options()...); EnvelopeVerdict(err) != v.ExpectNoPrev {
				t.Errorf("%s without the previous key: %v, want %s", v.Name, err, v.ExpectNoPrev)
			}
		}
	}
}

// The same documents, encrypted by this package, get the same verdicts: the envelope rules do not
// depend on who encrypted.
func TestTheSameDocumentsEncryptedHereGetTheSameVerdicts(t *testing.T) {
	f := loadEnvelopeFixtures(t)
	checked := 0
	for _, v := range f.Vectors {
		if v.PlaintextB64 == nil || v.Key != "current" || v.Expect == "decrypt_error" {
			continue
		}
		enc := envelopeEncrypter(t, f, v.Cipher, false)
		token, err := enc.EncryptString(string(mustB64Decode(t, *v.PlaintextB64)))
		if err != nil {
			t.Fatal(err)
		}
		o, err := enc.Open(token, v.Scope, v.options()...)
		v.check(t, "re-encrypted ", o, err)
		checked++
	}
	if checked < 120 {
		t.Errorf("only %d vectors re-encrypted", checked)
	}
}

func TestTokensThatAreNotEnvelopesAreInvalidNotDecryptErrors(t *testing.T) {
	enc := newEnc(t, "aes-256-cbc")
	cookie, _ := enc.EncryptCookie("laravel_session", "abc")
	serialized, _ := enc.Encrypt("hello")
	for name, token := range map[string]string{
		"string": mustEncrypt(t, enc, "hello"), "cookie": cookie, "serialized": serialized,
	} {
		if _, err := enc.Open(token, "s"); !errors.Is(err, ErrEnvelopeInvalid) {
			t.Errorf("%s: err = %v, want ErrEnvelopeInvalid", name, err)
		}
	}
}

// --- sealing ---

const envelopeNow = 1_700_000_000

func clock(unix int64) EnvelopeOption {
	return WithClock(func() time.Time { return time.Unix(unix, 0) })
}

func TestEnvelopeRoundTripsEveryKindOfData(t *testing.T) {
	values := []any{
		nil, true, int64(0), int64(-7), 1.5, "", "Grüße 世界 🚀 \"q\" \\ / <t> &",
		[]any{}, map[string]any{}, []any{1.0, "two", []any{3.0}, nil}, map[string]any{"a": map[string]any{"b": nil}},
	}
	for _, c := range allCiphers {
		enc := newEnc(t, c)
		for _, v := range values {
			token, err := enc.Seal("test", v, ExpiresIn(time.Minute))
			if err != nil {
				t.Fatalf("%s: %v", c, err)
			}
			o, err := enc.Open(token, "test")
			if err != nil {
				t.Fatalf("%s: %v", c, err)
			}
			var got any
			if err := o.Decode(&got); err != nil {
				t.Fatal(err)
			}
			want := v
			if b, err := json.Marshal(v); err == nil {
				_ = json.Unmarshal(b, &want)
			}
			if !reflect.DeepEqual(got, want) || o.Scope != "test" {
				t.Errorf("%s: got %#v, want %#v", c, got, want)
			}
		}
	}
}

func TestEnvelopeDataDecodesIntoGoTypes(t *testing.T) {
	type reset struct {
		User  int    `json:"user"`
		Email string `json:"email"`
	}
	enc := newEnc(t, "aes-256-gcm")
	token, err := enc.Seal("password-reset", reset{7, "a@b.c"}, NeverExpires())
	if err != nil {
		t.Fatal(err)
	}
	o, err := enc.Open(token, "password-reset")
	if err != nil {
		t.Fatal(err)
	}
	var got reset
	if err := o.Decode(&got); err != nil || got != (reset{7, "a@b.c"}) {
		t.Fatalf("Decode = %+v, %v", got, err)
	}
	if err := o.Decode(&[]int{}); err == nil {
		t.Error("Decode into the wrong type must fail")
	}
	if !strings.Contains(string(o.Data), "a@b.c") {
		t.Errorf("Data = %s", o.Data)
	}
}

func TestEnvelopeReportsTheTimestamps(t *testing.T) {
	enc := newEnc(t, "aes-256-cbc")
	open := func(expiry Expiry, opts ...EnvelopeOption) *Opened {
		t.Helper()
		token, err := enc.Seal("s", 1, expiry, append(opts, clock(envelopeNow))...)
		if err != nil {
			t.Fatal(err)
		}
		o, err := enc.Open(token, "s", clock(envelopeNow+20), WithLeeway(100*time.Second))
		if err != nil {
			t.Fatal(err)
		}
		return o
	}

	o := open(ExpiresIn(time.Hour), WithNotBefore(time.Unix(envelopeNow+10, 0)))
	if o.IssuedAt.Unix() != envelopeNow || o.NotBefore.Unix() != envelopeNow+10 || o.ExpiresAt.Unix() != envelopeNow+3600 {
		t.Errorf("timestamps = %v %v %v", o.IssuedAt, o.NotBefore, o.ExpiresAt)
	}
	if o := open(NeverExpires()); !o.NotBefore.IsZero() || !o.ExpiresAt.IsZero() {
		t.Errorf("none expected, got %v %v", o.NotBefore, o.ExpiresAt)
	}
	if o := open(ExpiresAt(time.Unix(envelopeNow+99, 0))); o.ExpiresAt.Unix() != envelopeNow+99 {
		t.Errorf("exp = %v", o.ExpiresAt)
	}
}

func TestEnvelopeChecksScopeExpiryAndNotBeforeAgainstTheClock(t *testing.T) {
	enc := newEnc(t, "aes-256-cbc")
	token, _ := enc.Seal("s", 1, ExpiresIn(100*time.Second), clock(envelopeNow), WithNotBefore(time.Unix(envelopeNow+50, 0)))
	at := func(offset int64, scope string, leeway time.Duration) error {
		_, err := enc.Open(token, scope, clock(envelopeNow+offset), WithLeeway(leeway))
		return err
	}

	for _, c := range []struct {
		offset  int64
		scope   string
		leeway  time.Duration
		verdict string
	}{
		{49, "s", 0, "not_yet_valid"}, {50, "s", 0, "ok"}, {99, "s", 0, "ok"}, {100, "s", 0, "expired"},
		{60, "other", 0, "scope_mismatch"}, {500, "other", 0, "scope_mismatch"}, // the scope is judged first
		{40, "s", 10 * time.Second, "ok"}, {39, "s", 10 * time.Second, "not_yet_valid"},
		{109, "s", 10 * time.Second, "ok"}, {110, "s", 10 * time.Second, "expired"},
	} {
		if got := EnvelopeVerdict(at(c.offset, c.scope, c.leeway)); got != c.verdict {
			t.Errorf("now+%d scope %q leeway %v: %s, want %s", c.offset, c.scope, c.leeway, got, c.verdict)
		}
	}
}

func TestEnvelopeUsesTheRealClockByDefault(t *testing.T) {
	enc := newEnc(t, "aes-256-cbc")
	live, _ := enc.Seal("s", "x", ExpiresIn(time.Minute))
	if _, err := enc.Open(live, "s"); err != nil {
		t.Errorf("live token: %v", err)
	}
	dead, _ := enc.Seal("s", "x", ExpiresAt(time.Unix(1, 0)))
	if _, err := enc.Open(dead, "s"); !errors.Is(err, ErrExpired) {
		t.Errorf("dead token: err = %v, want ErrExpired", err)
	}
}

func TestSealRejectsArgumentsThatCannotMakeAGoodEnvelope(t *testing.T) {
	enc := newEnc(t, "aes-256-cbc")
	for name, call := range map[string]func() error{
		"empty scope":        func() error { _, err := enc.Seal("", 1, NeverExpires()); return err },
		"zero expiry":        func() error { _, err := enc.Seal("s", 1, Expiry{}); return err },
		"lifetime too short": func() error { _, err := enc.Seal("s", 1, ExpiresIn(999*time.Millisecond)); return err },
		"negative lifetime":  func() error { _, err := enc.Seal("s", 1, ExpiresIn(-time.Second)); return err },
		"expiry before 1970": func() error { _, err := enc.Seal("s", 1, ExpiresAt(time.Unix(-5, 0))); return err },
		"unencodable data":   func() error { _, err := enc.Seal("s", make(chan int), NeverExpires()); return err },
	} {
		err := call()
		if err == nil {
			t.Errorf("%s: expected an error", name)
		} else if EnvelopeVerdict(err) == "ok" {
			t.Errorf("%s: verdict ok for %v", name, err)
		}
	}
}

func TestEnvelopePreviousKeysApply(t *testing.T) {
	old := newEncWithKey(t, "aes-256-cbc", 0x7a)
	token, _ := old.Seal("s", "legacy", ExpiresIn(time.Minute))
	rotated, err := New("base64:"+b64Encode(rawKey("aes-256-cbc", 0x2b)), "aes-256-cbc",
		WithPreviousKeys("base64:"+b64Encode(rawKey("aes-256-cbc", 0x7a))))
	if err != nil {
		t.Fatal(err)
	}
	if o, err := rotated.Open(token, "s"); err != nil || string(o.Data) != `"legacy"` {
		t.Errorf("rotated: %v %v", o, err)
	}
	if _, err := newEnc(t, "aes-256-cbc").Open(token, "s"); EnvelopeVerdict(err) != "decrypt_error" {
		t.Errorf("without the previous key: %v", err)
	}
}

func TestAPayloadThatDoesNotDecryptKeepsItsDecryptError(t *testing.T) {
	_, err := newEnc(t, "aes-256-cbc").Open("not a payload", "s")
	if !errors.Is(err, ErrInvalidPayload) || EnvelopeVerdict(err) != "decrypt_error" {
		t.Errorf("err = %v, verdict %s", err, EnvelopeVerdict(err))
	}
}

func TestEnvelopeVerdictNames(t *testing.T) {
	for err, want := range map[error]string{
		nil:                   "ok",
		ErrEnvelopeInvalid:    "invalid",
		ErrUnsupportedVersion: "unsupported_version",
		ErrScopeMismatch:      "scope_mismatch",
		ErrNotYetValid:        "not_yet_valid",
		ErrExpired:            "expired",
		ErrInvalidMAC:         "decrypt_error",
		ErrDecrypt:            "decrypt_error",
	} {
		if got := EnvelopeVerdict(err); got != want {
			t.Errorf("EnvelopeVerdict(%v) = %s, want %s", err, got, want)
		}
	}
}
